<script setup lang="ts">
import { onUnmounted, ref, watch } from 'vue';
import type { Plan } from './workbench';import { parsePlan } from './workbench';import { useDispatchStore } from './stores/dispatch';
const props=defineProps<{plan:Plan;available:boolean;mapId?:string;mapVersion?:string}>();const emit=defineEmits<{preview:[plan:Plan]}>();const store=useDispatchStore();
const projects=ref<any[]>([]),history=ref<any[]>([]),selected=ref(''),message=ref(''),busy=ref(false);const revisions=new Map<string,string>();let epoch=0;onUnmounted(()=>{++epoch;});
const key=(id:string)=>id.toLowerCase().replaceAll('-','');
watch(()=>props.available,()=>{++epoch;projects.value=[];history.value=[];selected.value='';revisions.clear();busy.value=false;});
async function run(fn:(n:number)=>Promise<void>){if(!props.available)return;const n=++epoch;busy.value=true;try{await fn(n);}catch(e){if(n===epoch)message.value=String(e);}finally{if(n===epoch)busy.value=false;}}
async function list(){await run(async n=>{const x=await store.api<any[]>('/api/projects');if(n===epoch)projects.value=x;});}
async function save(){await run(async n=>{const id=key(props.plan.id);const x:any=await store.api('/api/projects',{expectedRevision:revisions.get(id)??'',plan:JSON.parse(JSON.stringify(props.plan)),sourceMapId:props.mapId||null,sourceMapVersion:props.mapVersion||null});if(n===epoch){revisions.set(id,x.revision);message.value='服务端已保存版本 '+x.revision.slice(0,12)+'；未改运行图、车辆或任务参数。';const list=await store.api<any[]>('/api/projects');if(n===epoch)projects.value=list;}});}
async function preview(revision?:string){await run(async n=>{const x:any=await store.api('/api/projects/'+selected.value+(revision?'?revision='+revision:''));if(!x)throw new Error('存档不存在');const p=parsePlan(JSON.stringify(x.plan));if(n!==epoch)return;if(!revision)revisions.set(key(p.id),x.revision);emit('preview',p);message.value='已生成加载预览，确认前不替换编辑稿。历史版本加载后保存仍需以当前服务端revision核对。';});}
async function backup(){await run(async n=>{const x:any=await store.api('/api/projects/'+selected.value);const p=parsePlan(JSON.stringify(x.plan));if(n!==epoch)return;const url=URL.createObjectURL(new Blob([JSON.stringify(p,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='agv-project-'+x.revision.slice(0,12)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);message.value='已导出服务端方案；可从加载文件入口预览恢复，不自动激活或应用设备配置。';});}
async function versions(){await run(async n=>{const x=await store.api<any[]>('/api/projects/'+selected.value+'/history');if(n===epoch)history.value=x;});}
</script>
<template><section class="server-projects"><h3>服务端方案库</h3><p>按版本保留地图编辑稿、场景、车辆配置稿与航点顺序；服务端保存不等于应用到运行系统。跨电脑使用需导出方案文件带走，当前Web仅监听本机。</p><p v-if="!available">退出演示并连接后台后可用。</p><button :disabled="!available||busy" @click="list">读取服务端方案</button><button :disabled="!available||busy" @click="save">保存当前稿到服务端</button><select v-model="selected"><option value="">选择服务端方案</option><option v-for="p in projects" :key="p.id" :value="p.id">{{p.name}} · {{p.revision.slice(0,12)}}</option></select><button :disabled="!selected||busy||!available" @click="preview()">预览加载当前版本</button><button :disabled="!selected||busy||!available" @click="versions">版本历史</button><button :disabled="!selected||busy||!available" @click="backup">导出服务端方案备份</button><p role="status">{{message}}</p><div v-for="v in history" :key="v.revision"><code>{{v.revision.slice(0,12)}}</code> {{v.savedAt}} <button :disabled="busy||!available" @click="preview(v.revision)">预览此版本</button></div></section></template>
<style scoped>.server-projects{border:1px solid #365270;padding:18px;margin:14px 0}.server-projects p{font-size:12px;line-height:1.8}.server-projects button,.server-projects select{margin:5px}.server-projects select{max-width:320px}</style>
